# =============================================================================
# 05_manuscript_figures.R
# Purpose : generate the figures of the manuscript that are based on the ITS results, the
#           Mercado Livre listings and the ANVISA registry data. Output names follow the
#           manuscript numbering: Fig. 2, 3, 4 (Google Trends), Fig. 6, 7, 8, 9 (Mercado Livre),
#           Fig. 10 (ANVISA). Fig. 1 and Fig. 5A-C are generated by 06_time_series_figures.R.
# Inputs  : data/processed/its_results_classified.csv                     (script 03)
#           data/processed/ml_recategorized_scientific_final.csv          (scripts 04a-04d)
#           data/raw/ANVISA_RESULTS.xlsx                                  (manual consultation, 20 March 2024)
# Outputs : outputs/figures/*.png and outputs/tables/*.csv
# Run from the repository root.
# =============================================================================
OUT_FIG <- file.path("outputs", "figures")
OUT_TAB <- file.path("outputs", "tables")
dir.create(OUT_FIG, recursive = TRUE, showWarnings = FALSE)
dir.create(OUT_TAB, recursive = TRUE, showWarnings = FALSE)

# =============================================================================
# Figure 2 of the manuscript: Species with significant vs non-significant post-intervention
#           trend change in Google Trends (RENISUS impact)
# Input: its_results_classified.csv (generated by 03_gt_its_ols_newey_west.R)
# Output: Fig02_trend_significance.png
# =============================================================================

library(readr)
library(dplyr)
library(ggplot2)

# 1) Load ITS results
its <- read_csv(file.path("data", "processed", "its_results_classified.csv"), show_col_types = FALSE)

# 2) Summarize counts by trend effect category
summary_df <- its %>%
  count(Trend_Effect) %>%
  mutate(
    Trend_Effect = factor(
      Trend_Effect,
      levels = c("Positive", "Negative", "Non-significant")
    ),
    pct = round(100 * n / sum(n), 1),
    label = paste0(n, " (", pct, "%)")
  )

# 3) Plot
fig1 <- ggplot(summary_df, aes(x = Trend_Effect, y = n, fill = Trend_Effect)) +
  geom_col(width = 0.6) +
  geom_text(aes(label = label), vjust = -0.5, size = 4) +
  scale_fill_manual(
    values = c(
      "Positive" = "#2E8B57",
      "Negative" = "#B22222",
      "Non-significant" = "grey65"
    )
  ) +
  labs(
    title = "Species with significant vs non-significant post-intervention trend change",
    x = NULL,
    y = "Number of species"
  ) +
  ylim(0, max(summary_df$n) * 1.15) +
  theme_minimal(base_size = 13) +
  theme(
    legend.position = "none",
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text = element_text(color = "black")
  )

fig1

# 4) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig02_trend_significance.png"),
  plot = fig1,
  width = 7, height = 6, dpi = 300
)

# =============================================================================
# Figure 3 of the manuscript: Top 15 species with positive post-intervention trend change
#           in Google Trends (RENISUS impact)
# Input: its_results_classified.csv (generated by 03_gt_its_ols_newey_west.R)
# Output: Fig03_top15_positive_trend.png
# =============================================================================

library(readr)
library(dplyr)
library(ggplot2)
library(forcats)

# 1) Load ITS results
its <- read_csv(file.path("data", "processed", "its_results_classified.csv"), show_col_types = FALSE)

# 2) Filter positive significant species and select top 15 by coefficient magnitude
top_positive <- its %>%
  filter(Trend_Effect == "Positive") %>%
  arrange(desc(Trend_Coef)) %>%
  slice_head(n = 15) %>%
  mutate(
    Species = fct_reorder(Species, Trend_Coef),
    label = sprintf("%.2f", Trend_Coef)
  )

# 3) Plot
fig2 <- ggplot(top_positive, aes(x = Species, y = Trend_Coef)) +
  geom_col(fill = "#2E8B57", width = 0.7) +
  geom_text(aes(label = label), hjust = -0.15, size = 3.6) +
  coord_flip() +
  labs(
    title = "Top 15 species with positive trend change after RENISUS",
    x = NULL,
    y = "Post-intervention trend coefficient (β)"
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.18))) +
  theme_minimal(base_size = 13) +
  theme(
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text.y = element_text(face = "italic", color = "black"),
    axis.text.x = element_text(color = "black")
  )

fig2

# 4) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig03_top15_positive_trend.png"),
  plot = fig2,
  width = 8, height = 7, dpi = 300
)


