# =============================================================================
# Figure 6 of the manuscript: Distribution of Mercado Livre listings by category
# Input: ml_recategorized_scientific_final.csv (recategorized listings, before deduplication)
# Output: Fig06_category_distribution.png
# =============================================================================

library(readr)
library(dplyr)
library(ggplot2)
library(forcats)
library(scales)

# 1) Load raw recategorized data
ml_raw <- read_csv(file.path("data", "processed", "ml_recategorized_scientific_final.csv"), show_col_types = FALSE)

# 2) Remove duplicate listings
# During scraping, each Mercado Livre listing (identified by its unique
# combination of `source` species and `ID`) was matched against BOTH its
# original marketplace category (e.g. "Saude", "Suplementos Alimentares")
# AND a scientific/taxon-based recategorization pass. When a listing matched
# more than one category rule, it was written out once per matching rule,
# producing multiple rows for the same physical ad (e.g. ID MLB3344505617
# appears once as "Health" and once as "Dietary Supplements"). This inflates
# category counts (~4,945 extra rows, ~33% of the raw file) and must be
# corrected before any frequency analysis. We keep only the first occurrence
# per (source, ID) pair, which corresponds to the primary category assigned
# during recategorization.
ml_dedup <- ml_raw %>%
  distinct(source, ID, .keep_all = TRUE)

cat("Rows before deduplication:", nrow(ml_raw), "\n")
cat("Rows after deduplication:", nrow(ml_dedup), "\n")
cat("Duplicate rows removed:", nrow(ml_raw) - nrow(ml_dedup), "\n")

# 3) Summarize by final category
cat_summary <- ml_dedup %>%
  count(CATEGORY_final, name = "n") %>%
  mutate(
    pct = round(100 * n / sum(n), 1),
    label = paste0(comma(n), " (", pct, "%)"),
    CATEGORY_final = fct_reorder(CATEGORY_final, n)
  )

# 4) Save cleaned summary for reuse in other figures/tables
write_csv(cat_summary, file.path(OUT_TAB, "cat_summary_final.csv"))

# 5) Plot (horizontal bars, log scale to accommodate wide range)
fig4 <- ggplot(cat_summary, aes(x = CATEGORY_final, y = n)) +
  geom_col(fill = "#1f77b4", width = 0.7) +
  geom_text(aes(label = label), hjust = -0.05, size = 3.6) +
  coord_flip() +
  scale_y_continuous(
    labels = comma,
    trans = "log10",
    expand = expansion(mult = c(0, 0.35))
  ) +
  labs(
    title = "Distribution of Mercado Livre listings by category",
    x = NULL,
    y = "Number of listings (log scale)"
  ) +
  theme_minimal(base_size = 13) +
  theme(
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text = element_text(color = "black")
  )

fig4

# 6) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig06_category_distribution.png"),
  plot = fig4,
  width = 8, height = 6, dpi = 300
)

# =============================================================================
# Figure 7 of the manuscript: Detection of scientific names in Mercado Livre listing titles
# Input: ml_recategorized_scientific_final.csv (recategorized listings, before deduplication)
# Output: Fig07_scientific_name_detection.png
# =============================================================================

library(readr)
library(dplyr)
library(ggplot2)
library(scales)

# 1) Load raw recategorized data
ml_raw <- read_csv(file.path("data", "processed", "ml_recategorized_scientific_final.csv"), show_col_types = FALSE)

# 2) Remove duplicate listings
# Same duplication issue as Figure 4: each listing can appear once per
# matched category rule (marketplace category vs. scientific recategorization),
# inflating counts. We keep only the first occurrence per (source, ID) pair.
ml_dedup <- ml_raw %>%
  distinct(source, ID, .keep_all = TRUE)

cat("Rows before deduplication:", nrow(ml_raw), "\n")
cat("Rows after deduplication:", nrow(ml_dedup), "\n")

# 3) Classify listings by name detection type
# BY_SCIENTIFIC_NAME = TRUE means the listing title matched a scientific
# name (species- or genus-level, per SCIENTIFIC_MATCH_TYPE). All remaining
# listings were matched only by common/popular name (the search term used
# during scraping), regardless of whether the title itself used a colloquial name.
name_summary <- ml_dedup %>%
  mutate(
    Match_Type = case_when(
      SCIENTIFIC_MATCH_TYPE == "species" ~ "Scientific name (species)",
      SCIENTIFIC_MATCH_TYPE == "genus"   ~ "Scientific name (genus)",
      TRUE                               ~ "Popular name only"
    ),
    Match_Type = factor(
      Match_Type,
      levels = c("Popular name only", "Scientific name (genus)", "Scientific name (species)")
    )
  ) %>%
  count(Match_Type, name = "n") %>%
  mutate(
    pct = round(100 * n / sum(n), 1),
    label = paste0(comma(n), " (", pct, "%)")
  )

# 4) Save summary for reuse
write_csv(name_summary, file.path(OUT_TAB, "name_summary_final.csv"))

# 5) Plot
fig5 <- ggplot(name_summary, aes(x = Match_Type, y = n, fill = Match_Type)) +
  geom_col(width = 0.6) +
  geom_text(aes(label = label), vjust = -0.5, size = 4) +
  scale_fill_manual(
    values = c(
      "Popular name only" = "grey65",
      "Scientific name (genus)" = "#4682B4",
      "Scientific name (species)" = "#1f3d5c"
    )
  ) +
  labs(
    title = "Detection of scientific names in Mercado Livre listing titles",
    x = NULL,
    y = "Number of listings"
  ) +
  scale_y_continuous(labels = comma, expand = expansion(mult = c(0, 0.15))) +
  theme_minimal(base_size = 13) +
  theme(
    legend.position = "none",
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text = element_text(color = "black"),
    axis.text.x = element_text(angle = 15, hjust = 1)
  )

fig5

# 6) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig07_scientific_name_detection.png"),
  plot = fig5,
  width = 7.5, height = 6, dpi = 300
)

# =============================================================================
# Figure 8 of the manuscript: Top 15 most advertised species on Mercado Livre
# Note: species are identified by their popular Brazilian Portuguese name
# (the original search term used during data collection), not by scientific
# name. Popular names are kept as-is per editorial decision, so axis labels
# are NOT italicized (italics are reserved for binomial scientific names).
# Input: ml_recategorized_scientific_final.csv (recategorized listings, before deduplication)
# Output: Fig08_top15_most_advertised.png
# =============================================================================

library(readr)
library(dplyr)
library(ggplot2)
library(forcats)
library(scales)

# 1) Load raw recategorized data
ml_raw <- read_csv(file.path("data", "processed", "ml_recategorized_scientific_final.csv"), show_col_types = FALSE)

# 2) Remove duplicate listings
# Same duplication issue as previous figures: each listing can appear once
# per matched category rule (marketplace category vs. scientific
# recategorization), inflating counts. We keep only the first occurrence
# per (source, ID) pair.
ml_dedup <- ml_raw %>%
  distinct(source, ID, .keep_all = TRUE)

cat("Rows before deduplication:", nrow(ml_raw), "\n")
cat("Rows after deduplication:", nrow(ml_dedup), "\n")

# 3) Count listings per species (source = popular name search term)
species_summary <- ml_dedup %>%
  count(source, name = "n") %>%
  arrange(desc(n))

# 4) Select top 15 most advertised species
top_most <- species_summary %>%
  slice_head(n = 15) %>%
  mutate(
    source = fct_reorder(source, n),
    label = comma(n)
  )

# 5) Save full ranking for reference/appendix
write_csv(species_summary, file.path(OUT_TAB, "species_ranking_full.csv"))

# 6) Plot
fig6 <- ggplot(top_most, aes(x = source, y = n)) +
  geom_col(fill = "#2E8B57", width = 0.7) +
  geom_text(aes(label = label), hjust = -0.15, size = 3.6) +
  coord_flip() +
  labs(
    title = "Top 15 most advertised species on Mercado Livre",
    x = NULL,
    y = "Number of listings"
  ) +
  scale_y_continuous(labels = comma, expand = expansion(mult = c(0, 0.15))) +
  theme_minimal(base_size = 13) +
  theme(
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text = element_text(color = "black")
  )

fig6

# 7) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig08_top15_most_advertised.png"),
  plot = fig6,
  width = 8, height = 7, dpi = 300
)

