# =============================================================================
# Figure 10 of the manuscript: RENISUS species with valid vs non-valid ANVISA registry
# Classification rule (confirmed with advisor):
#   - "V"   -> Valid registry
#   - "C/V" -> Valid registry (species has at least one active registration,
#              even though another registration was cancelled)
#   - "C"   -> No valid registry (all registrations cancelled)
#   - ""/NA -> No valid registry (no registration found)
# Input: ANVISA_RESULTS.xlsx
# Output: Fig10_anvisa_registry.png
# =============================================================================

library(readxl)
library(dplyr)
library(ggplot2)
library(scales)

# 1) Load ANVISA registry data
# The sheet has 6 columns (4 are empty/logical) and the real header
# ("Espécie" / "Registro...") was imported as the first data row instead
# of as column names. We select only the first 2 columns, drop that
# header row, then assign clean names manually.
anvisa_raw <- read_excel(
  file.path("data", "raw", "ANVISA_RESULTS.xlsx"),
  sheet = 1
) %>%
  select(1:2) %>%
  slice(-1)

names(anvisa_raw) <- c("Species", "Registry_raw")

print(dim(anvisa_raw))
print(head(anvisa_raw))

# 2) Classify registry status
# Any value containing "V" (i.e. "V" or "C/V") is treated as valid, since the
# species has at least one active registration. "C" alone or a blank value
# means no valid registration exists.
anvisa <- anvisa_raw %>%
  mutate(
    Registry_raw = trimws(Registry_raw),
    Registry_Status = case_when(
      is.na(Registry_raw) | Registry_raw == "" ~ "No valid registry",
      grepl("V", Registry_raw, fixed = TRUE) ~ "Valid registry",
      TRUE ~ "No valid registry"
    )
  )

cat("Total species:", nrow(anvisa), "\n")
print(table(anvisa$Registry_Status))

# 3) Summarize
registry_summary <- anvisa %>%
  count(Registry_Status, name = "n") %>%
  mutate(
    pct = round(100 * n / sum(n), 1),
    label = paste0(n, " (", pct, "%)"),
    Registry_Status = factor(Registry_Status, levels = c("Valid registry", "No valid registry"))
  )

write_csv(registry_summary, file.path(OUT_TAB, "anvisa_registry_summary.csv"))

# 4) Plot
fig8 <- ggplot(registry_summary, aes(x = Registry_Status, y = n, fill = Registry_Status)) +
  geom_col(width = 0.55) +
  geom_text(aes(label = label), vjust = -0.5, size = 4.2) +
  scale_fill_manual(
    values = c(
      "Valid registry" = "#2E8B57",
      "No valid registry" = "#B22222"
    )
  ) +
  labs(
    title = "RENISUS species with valid vs non-valid ANVISA registry",
    x = NULL,
    y = "Number of species"
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
  theme_minimal(base_size = 13) +
  theme(
    legend.position = "none",
    plot.title = element_text(face = "bold", size = 13, hjust = 0.5),
    axis.text = element_text(color = "black")
  )

fig8

# 5) Export publication-ready PNG
ggsave(
  file.path(OUT_FIG, "Fig10_anvisa_registry.png"),
  plot = fig8,
  width = 7, height = 6, dpi = 300
)